  [NormedAddCommGroup E] [InnerProductSpace ℝ E] [CompleteSpace E] [SecondCountableTopology E]
  [MeasurableSpace E] [BorelSpace E] {f : E → ℝ} {L : NNReal} {μ : MeasureTheory.Measure E}
  [ProbabilityTheory.IsGaussian μ] (hf : ContDiff ℝ 1 f) (hL : ∀ (x : E), ‖gradient f x‖ ≤ ↑L)
  (t : ℝ) : MeasureTheory.Integrable (fun x => Real.exp (t * f x)) μ

Learning.map_stoppedProcess_sigmaHistory:
Learning.map_stoppedProcess_sigmaHistory_eq_add.{u_1, u_2, u_3, u_4} {𝓞 : Type u_1} {𝓐 : Type u_2}
  {𝓨 : Type u_3} {m𝓞 : MeasurableSpace 𝓞} {m𝓐 : MeasurableSpace 𝓐} {m𝓨 : MeasurableSpace 𝓨}
  {Ω : Type u_4} {mΩ : MeasurableSpace Ω} {O : ℕ → Ω → 𝓞} {X : ℕ → Ω → 𝓐} {Y : ℕ → Ω → 𝓨}
  {τ : Ω → WithTop ℕ} (hO : ∀ (n : ℕ), Measurable (O n)) (hX : ∀ (n : ℕ), Measurable (X n))
  (hY : ∀ (n : ℕ), Measurable (Y n)) {P : MeasureTheory.Measure Ω} (hτ : Measurable τ) (M : ℕ) :
  MeasureTheory.Measure.map (MeasureTheory.stoppedProcess (Learning.sigmaHistory O X Y) τ M) P =
    MeasureTheory.Measure.map (MeasureTheory.stoppedProcess (Learning.sigmaHistory O X Y) τ M)
        (P.restrict {ω | τ ω ≤ ↑M}) +
      MeasureTheory.Measure.map (Sigma.mk M)
        (MeasureTheory.Measure.map (Learning.history O X Y M) (P.restrict {ω | ↑M < τ ω}))

