Learning.lt_hittingAfter_sigmaHistory_if:
Learning.lt_hittingAfter_sigmaHistory_iff.{u_1, u_2, u_3, u_4} {𝓞 : Type u_1} {𝓐 : Type u_2}
  {𝓨 : Type u_3} {Ω : Type u_4} {O : ℕ → Ω → 𝓞} {X : ℕ → Ω → 𝓐} {Y : ℕ → Ω → 𝓨}
